struct NthElement(usize);
impl<'de> Visitor<'de> for NthElement {
 type Value=Vec<u32>;
 fn expecting(&self,f:&mut fmt::Formatter)->fmt::Result { write!(f,"a sequence with element {}",self.0) }
 fn visit_seq<A:SeqAccess<'de>>(self,mut seq:A)->Result<Vec<u32>,A::Error> {
  for i in 0..self.0 {
   if seq.next_element::<IgnoredAny>()?.is_none() { return Err(A::Error::invalid_length(i,&self)); }
  }
  let nth=match seq.next_element()? { Some(v)=>v,None=>return Err(A::Error::invalid_length(self.0,&self)) };
  while let Some(IgnoredAny)=seq.next_element()? {}
  Ok(nth)
 }
}
