use serde_derive_internals::Ctxt;
let original = Ctxt::new();
original.error_spanned_by("field", "invalid field");
let first = original.check();
match first {
    Ok(()) => obs(false),
    Err(error) => {
        let second = Ctxt::new();
        second.syn_error(error);
        obs(second.check().is_err())
    }
}

